    facts:[["Headquarters","Suva"],["Special industrial district","Nouméa"],["Eastern deputy government","Papeete"],["Principal territories","Fiji, New Caledonia, Wallis and Futuna, and French Polynesia"],["Status","Direct Japanese imperial territory"],["Nationality","Japanese"]]
