    facts:[["State applying doctrine","Empire of Japan"],["Primary field","Associated statehood"],["Core tests","Government, revenue, communications, law, defense, diplomacy, and economy"],["Principal qualifying case","Papua New Guinea"],["Principal disputed cases","Fiji, New Caledonia, and Tahiti"],["Effect of approval","Associated statehood"],["Effect of rejection","Direct imperial administration"],["Official Japanese title","Open"]]
